record.field:
# 1. POSITION RULE PRIORITY
pos_val = 0.0
emp_pos = (contract.job_id if 'job_id' in contract._fields else False) or (employee.job_id if 'job_id' in employee._fields else False)
if emp_pos and rule and rule.position_rules:
    matching_pos = rule.position_rules.filtered(lambda r: r.position == emp_pos)
    if matching_pos:
        pos_val = matching_pos[0].value or 0.0

# 2. GRADE RULE PRIORITY
grade_val = 0.0
emp_grade = (
    (contract.grade_id if 'grade_id' in contract._fields and contract.grade_id else False)
    or (contract.job_grade if 'job_grade' in contract._fields and contract.job_grade else False)
    or (employee.grade_id if 'grade_id' in employee._fields and employee.grade_id else False)
    or (employee.job_grade if 'job_grade' in employee._fields and employee.job_grade else False)
)

if emp_grade and rule and rule.grade_rules:
    emp_code = (
        (emp_grade.grade_code if 'grade_code' in emp_grade._fields and emp_grade.grade_code else '')
        or (emp_grade.code if 'code' in emp_grade._fields and emp_grade.code else '')
        or (emp_grade.grade_name if 'grade_name' in emp_grade._fields and emp_grade.grade_name else '')
        or (emp_grade.name if 'name' in emp_grade._fields and emp_grade.name else '')
    ).strip().upper()

    matching_grade = rule.grade_rules.filtered(
        lambda r: r.grade2 == emp_grade or (
            r.grade2 and emp_code and (
                (r.grade2.grade_code if 'grade_code' in r.grade2._fields and r.grade2.grade_code else '')
                or (r.grade2.grade_name if 'grade_name' in r.grade2._fields and r.grade2.grade_name else '')
                or (r.grade2.code if 'code' in r.grade2._fields and r.grade2.code else '')
                or (r.grade2.name if 'name' in r.grade2._fields and r.grade2.name else '')
            ).strip().upper() == emp_code
        )
    )
    if matching_grade:
        grade_val = matching_grade[0].value or matching_grade[0].base_salary or 0.0

if pos_val > 0:
    result = pos_val
elif grade_val > 0:
    result = grade_val
else:
    result = rule.value or 0.0

ou = contract.operating_unit_id or employee.default_operating_unit_id
if not ou and employee.department_id:
    ou = employee.department_id.operating_unit_id

ou_rate = 0.0
if ou:
    try:
        ou_rate = (ou.hardship_allowance or 0.0) / 100.0
    except Exception:
        ou_rate = 0.0
    if ou_rate == 0.0:
        try:
            contract.env.cr.execute("SELECT hardship_allowance FROM operating_unit WHERE id = %s", (ou.id,))
            row = contract.env.cr.fetchone()
            if row and row[0]:
                ou_rate = float(row[0]) / 100.0
        except Exception:
            pass

if ou_rate > 0:
    result = categories.BASIC * ou_rate
else:
    result = 0.0

try:
    all_lines = adj_lines
except Exception:
    all_lines = False
if all_lines is False or all_lines is None:
    all_lines = employee.env['hr.payroll.adjustment.line'].search([('employee_id', '=', employee.id), ('active', '=', True), ('adjustment_id.active', '=', True)]) if 'hr.payroll.adjustment.line' in employee.env else False
p_id = payslip.period_id if hasattr(payslip, 'period_id') and payslip.period_id else False
cia_lines = [l for l in (all_lines or []) if (l.code in ('CIA', 'CIA-ALL', 'CASH_INDEMNITY') or (l.adjustment_id and l.adjustment_id.code in ('CIA', 'CIA-ALL', 'CASH_INDEMNITY')) or (l.ciamount and l.ciamount > 0))]
if p_id and cia_lines:
    matched = [l for l in cia_lines if (l.adjustment_id.period_id and l.adjustment_id.period_id == p_id) or (p_id.name and p_id.name.lower() in (l.adjustment_id.name or '').lower())]
    if matched:
        cia_lines = matched
    else:
        unassigned = [l for l in cia_lines if not l.adjustment_id.period_id or l.adjustment_id.period_id == p_id]
        if unassigned:
            latest_id = max(l.adjustment_id.id for l in unassigned if l.adjustment_id)
            cia_lines = [l for l in unassigned if l.adjustment_id and l.adjustment_id.id == latest_id]
        else:
            cia_lines = []
result = sum(l.ciamount for l in cia_lines if l.ciamount) if cia_lines else (contract.cash_indemnity if 'cash_indemnity' in contract._fields and contract.cash_indemnity else 0.0)

try:
