ciab_lines = [l for l in (all_lines or []) if (l.code in ('CIAB', 'CIA', 'CIA-ALL', 'CASH_INDEMNITY') or (l.adjustment_id and (l.adjustment_id.code in ('CIAB', 'CIA', 'CIA-ALL', 'CASH_INDEMNITY') or 'CASH INDEMNITY' in (l.adjustment_id.name or '').upper())) or (l.ciamount and l.ciamount > 0)) and l.amount > 0]

if p_id:
    matched_cia = [l for l in cia_lines if ((getattr(l.adjustment_id, 'payroll_period_id', False) and l.adjustment_id.payroll_period_id == p_id) or (l.adjustment_id.period_id and l.adjustment_id.period_id == p_id)) or (p_id.name and p_id.name.lower() in (l.adjustment_id.name or '').lower())]
    if matched_cia:
        cia_lines = matched_cia
    matched_ciab = [l for l in ciab_lines if ((getattr(l.adjustment_id, 'payroll_period_id', False) and l.adjustment_id.payroll_period_id == p_id) or (l.adjustment_id.period_id and l.adjustment_id.period_id == p_id)) or (p_id.name and p_id.name.lower() in (l.adjustment_id.name or '').lower())]
    if matched_ciab:
        ciab_lines = matched_ciab

cia_amt = sum(l.ciamount for l in cia_lines if l.ciamount) if cia_lines else (contract.cash_indemnity if 'cash_indemnity' in contract._fields and contract.cash_indemnity else 0.0)
adj_amt = sum(l.amount for l in ciab_lines) if ciab_lines else (contract.cash_indemnity_bank if 'cash_indemnity_bank' in contract._fields and contract.cash_indemnity_bank else 0.0)

result = round(categories.BASIC + categories.ALW - cia_amt + adj_amt, 2)

ou = contract.operating_unit_id or employee.default_operating_unit_id
if not ou and employee.department_id:
    ou = employee.department_id.operating_unit_id

ou_exempt_rate = 0.0
if ou:
    try:
        ou_exempt_rate = (ou.tax_exempt or 0.0) / 100.0
    except Exception:
        ou_exempt_rate = 0.0
    if ou_exempt_rate == 0.0:
        try:
            contract.env.cr.execute("SELECT tax_exempt FROM operating_unit WHERE id = %s", (ou.id,))
            row = contract.env.cr.fetchone()
            if row and row[0]:
                ou_exempt_rate = float(row[0]) / 100.0
        except Exception:
            pass

hardship_exempt = categories.BASIC * ou_exempt_rate

# Fuel Exemption (statutory 600 max)
fuel_exempt = 0.0
if (contract.special_car_allowance or 0) == 0 and (contract.fuel_exempted_1 or 0) != 1:
    f_val = 0.0
    try:
        f_val = float(FUEL)
    except Exception:
        f_val = float(contract.fuel_allowance or 0.0)
    fuel_exempt = min(f_val, 600.0)

# Transportation Exemption (statutory 2200 max)
trans_exempt = 0.0
if (contract.special_car_allowance or 0) == 0:
    t_val = 0.0
    try:
        t_val = float(TRANSPORT)
    except Exception:
        t_val = float(contract.transportation_allowance or 0.0)
    trans_exempt = min(t_val, 2200.0)

other_exempt = float(contract.total_tax_exemption or 0.0)
result = round(hardship_exempt + fuel_exempt + trans_exempt + other_exempt, 2)

try:
    all_lines = adj_lines
