balance = contract.cost_sharing_balance or 0.0
paid = contract.cost_sharing or 0.0
try:
    contract.env.cr.execute("SELECT COALESCE(cost_sharing_balance, 0.0), COALESCE(cost_sharing, 0.0) FROM hr_version WHERE id = %s", (contract.id,))
    row = contract.env.cr.fetchone()
    if row:
        balance = float(row[0] or 0.0)
        paid = float(row[1] or 0.0)
except Exception:
    pass

remaining = max(0.0, round(balance - paid, 2))
if balance > 0 and remaining > 0:
    monthly_rate = categories.BASIC * 0.10
    result = round(min(monthly_rate, remaining), 2)
else:
    result = 0.0

